package com.shiguang.snap;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.provider.MediaStore;
import android.view.*;
import android.widget.*;
import android.text.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
    final int INK=Color.rgb(41,51,46), ORANGE=Color.rgb(239,97,49), PAPER=Color.rgb(248,246,239);
    LinearLayout page; Bitmap original; ImageView preview; boolean square=false,border=true,editing=false,busy=false; String caption="";
    final ExecutorService worker=Executors.newSingleThreadExecutor();
    int dp(float n){return (int)(n*getResources().getDisplayMetrics().density);}
    @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().getDecorView().setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets;});home();}
    GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(4),1);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    void gap(LinearLayout parent,int h){Space v=new Space(this);parent.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
    LinearLayout column(int color){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(dp(20),dp(20),dp(20),dp(20));l.setBackground(bg(color,24));return l;}
    void base(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(PAPER);page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(24),dp(20),dp(24),dp(30));scroll.addView(page);setContentView(scroll);}
    TextView button(String s,boolean primary,Runnable action){TextView b=text(s,16,primary?Color.WHITE:INK,true);b.setGravity(Gravity.CENTER);b.setPadding(dp(14),dp(17),dp(14),dp(17));b.setBackground(bg(primary?ORANGE:Color.WHITE,16));b.setOnClickListener(v->action.run());return b;}
    void pick(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,10);}
    void home(){editing=false;base();LinearLayout header=new LinearLayout(this);TextView name=text("▣  拾光",25,INK,true);header.addView(name,new LinearLayout.LayoutParams(0,-2,1));TextView info=text("☰",25,INK,false);info.setContentDescription("关于拾光");info.setOnClickListener(v->about());header.addView(info);page.addView(header);gap(page,30);
        TextView kicker=text("MAKE A LITTLE SPACE",11,ORANGE,true);kicker.setLetterSpacing(.18f);page.addView(kicker);gap(page,10);page.addView(text("让截图，\n成为值得留住的片刻。",31,INK,true));gap(page,10);page.addView(text("裁剪 · 标注 · 美化，一张就够了。",14,0xff858980,false));gap(page,26);
        LinearLayout hero=column(0xffe8edde);hero.addView(text("灵感，随手收好                 ✦",21,INK,true));gap(hero,20);
        LinearLayout cards=new LinearLayout(this);LinearLayout a=column(0xfff5ddb0);a.addView(text("☀",35,ORANGE,false));gap(a,10);a.addView(text("收集生活的\n小小高光。",20,INK,true));gap(a,12);a.addView(text("A MOMENT TO KEEP",8,INK,false));a.setRotation(-4);LinearLayout.LayoutParams ca=new LinearLayout.LayoutParams(0,dp(185),1);ca.setMargins(0,0,dp(12),0);cards.addView(a,ca);
        LinearLayout b=column(Color.WHITE);b.addView(text("“",38,ORANGE,true));b.addView(text("好想法，\n不必转瞬即逝。",17,INK,true));gap(b,16);b.addView(text("━━━━",14,ORANGE,true));b.setRotation(4);cards.addView(b,new LinearLayout.LayoutParams(0,dp(185),1));hero.addView(cards);gap(hero,24);hero.addView(button("＋  导入截图，开始创作       ↗",true,()->pick()));gap(hero,12);hero.addView(text("照片仅在设备上处理，安心记录。",11,0xff798073,false));page.addView(hero);gap(page,28);
        page.addView(text("你的随身截图工具",19,INK,true));gap(page,14);LinearLayout tools=new LinearLayout(this);String[] titles={"⌗\n自由裁剪","✎\n随手标注","▤\n留白美化"};String[] subtitles={"留下重点","表达想法","让画面呼吸"};for(int n=0;n<3;n++){LinearLayout tile=column(Color.WHITE);tile.setPadding(dp(12),dp(16),dp(8),dp(16));tile.addView(text(titles[n],17,ORANGE,true));gap(tile,6);tile.addView(text(subtitles[n],10,0xff858980,false));tile.setOnClickListener(v->pick());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-1,1);p.setMargins(0,0,dp(n==2?0:9),0);tools.addView(tile,p);}page.addView(tools);gap(page,28);page.addView(text("最近创作",19,INK,true));gap(page,14);
        File[] files=works().listFiles((d,n)->n.endsWith(".png"));if(files==null||files.length==0){LinearLayout empty=column(Color.WHITE);TextView e=text("▧\n第一张作品，从这里开始",17,INK,true);e.setGravity(Gravity.CENTER);empty.addView(e);gap(empty,8);TextView note=text("保存后的创作会安静地待在这里",12,0xff858980,false);note.setGravity(Gravity.CENTER);empty.addView(note);page.addView(empty);}else{Arrays.sort(files,(x,y)->y.getName().compareTo(x.getName()));for(File f:files){ImageView iv=new ImageView(this);iv.setAdjustViewBounds(true);iv.setMaxHeight(dp(230));iv.setImageBitmap(decode(Uri.fromFile(f)));iv.setContentDescription("已保存的截图作品");iv.setOnClickListener(v->{original=decode(Uri.fromFile(f));if(original!=null){square=false;border=true;caption="";editor();}});page.addView(iv,new LinearLayout.LayoutParams(-1,dp(200)));gap(page,12);}}
        gap(page,28);TextView foot=text("拾光 SNAP  /  留住每一个好片刻",10,0xff858980,false);foot.setGravity(Gravity.CENTER);page.addView(foot);
    }
    File works(){File d=new File(getFilesDir(),"works");d.mkdirs();return d;}
    Bitmap decode(Uri uri){try{ImageDecoder.Source src=ImageDecoder.createSource(getContentResolver(),uri);return ImageDecoder.decodeBitmap(src,(decoder,info,source)->{int w=info.getSize().getWidth(),h=info.getSize().getHeight();float scale=Math.min(1f,1800f/Math.max(w,h));decoder.setTargetSize(Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)));decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);});}catch(Exception e){return null;}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==10&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri uri=data.getData();worker.execute(()->{Bitmap loaded=decode(uri);runOnUiThread(()->{if(loaded==null){toast("图片读取失败，请选择其他图片");return;}original=loaded;square=false;border=true;caption="";editor();});});}}
    void editor(){editing=true;base();page.addView(button("‹  返回工作台",false,()->home()));gap(page,24);page.addView(text("创作空间",28,INK,true));gap(page,8);page.addView(text("给这一刻，一点留白。",15,0xff858980,false));gap(page,24);preview=new ImageView(this);preview.setAdjustViewBounds(true);preview.setContentDescription("作品预览");page.addView(preview,new LinearLayout.LayoutParams(-1,dp(360)));gap(page,20);
        Switch crop=new Switch(this);crop.setText("正方形裁剪 · 保留图片中心");crop.setTextColor(INK);crop.setChecked(square);crop.setOnCheckedChangeListener((v,on)->{square=on;update();});page.addView(crop);Switch frame=new Switch(this);frame.setText("奶油留白");frame.setTextColor(INK);frame.setChecked(border);frame.setOnCheckedChangeListener((v,on)->{border=on;update();});page.addView(frame);gap(page,14);
        EditText input=new EditText(this);input.setSingleLine(true);input.setHint("写一句标注…");input.setText(caption);input.setTextSize(16);input.setPadding(dp(16),dp(12),dp(16),dp(12));input.setBackground(bg(Color.WHITE,14));input.setFilters(new InputFilter[]{new InputFilter.LengthFilter(60)});input.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){caption=s.toString();update();}public void afterTextChanged(Editable e){}});page.addView(input);gap(page,22);page.addView(button("↓  保存作品",true,()->export(false)));gap(page,12);page.addView(button("↗  分享这一刻",false,()->export(true)));update();
    }
    Bitmap render(){int w=original.getWidth(),h=original.getHeight(),cw=square?Math.min(w,h):w,ch=square?Math.min(w,h):h,p=border?48:0,footer=caption.isEmpty()?0:90;Bitmap out=Bitmap.createBitmap(cw+2*p,ch+2*p+footer,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(out);c.drawColor(0xfff7f2e6);c.drawBitmap(original,new Rect((w-cw)/2,(h-ch)/2,(w+cw)/2,(h+ch)/2),new Rect(p,p,p+cw,p+ch),new Paint(3));if(!caption.isEmpty()){Paint pen=new Paint(3);pen.setColor(INK);pen.setTextSize(Math.min(28,cw/12f));String line=android.text.TextUtils.ellipsize(caption,new android.text.TextPaint(pen),Math.max(1,cw-24),android.text.TextUtils.TruncateAt.END).toString();c.drawText(line,p+12,p+ch+50,pen);}return out;}
    void update(){if(preview!=null&&original!=null)preview.setImageBitmap(render());}
    void export(boolean share){if(busy)return;busy=true;Bitmap result=render();worker.execute(()->{Uri uri=null;boolean local=false;try{File target=new File(works(),System.currentTimeMillis()+".png");try(OutputStream out=new FileOutputStream(target)){if(!result.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("编码失败");}local=true;ContentValues cv=new ContentValues();cv.put(MediaStore.Images.Media.DISPLAY_NAME,target.getName());cv.put(MediaStore.Images.Media.MIME_TYPE,"image/png");cv.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/Shiguang");cv.put(MediaStore.Images.Media.IS_PENDING,1);uri=getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,cv);if(uri==null)throw new IOException("相册不可用");try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null||!result.compress(Bitmap.CompressFormat.PNG,100,out))throw new IOException("写入失败");}cv.clear();cv.put(MediaStore.Images.Media.IS_PENDING,0);getContentResolver().update(uri,cv,null,null);Uri saved=uri;runOnUiThread(()->{busy=false;toast("已保存到作品和系统相册");if(share){Intent send=new Intent(Intent.ACTION_SEND);send.setType("image/png");send.putExtra(Intent.EXTRA_STREAM,saved);send.setClipData(ClipData.newRawUri("拾光作品",saved));send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(send,"分享这一刻"));}});}catch(Exception e){if(uri!=null)getContentResolver().delete(uri,null,null);String msg=local?"作品已保存在应用内，相册写入失败":"保存失败，请重试";runOnUiThread(()->{busy=false;toast(msg);});}});}
    void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    void about(){LinearLayout content=column(PAPER);content.addView(text("拾光截图",27,INK,true));gap(content,14);content.addView(text("把重要的留下，把多余的裁掉。\n所有编辑均在本地完成，不上传照片。",15,INK,false));gap(content,20);ImageView badge=new ImageView(this);badge.setImageResource(com.shiguang.snap.R.drawable.store_badge);badge.setAdjustViewBounds(true);badge.setContentDescription("Google Play");content.addView(badge,new LinearLayout.LayoutParams(-1,dp(100)));gap(content,12);content.addView(text("Android 版 · 1.0",12,0xff858980,false));new AlertDialog.Builder(this).setView(content).setPositiveButton("完成",null).show();}
    @Override public void onBackPressed(){if(editing)home();else super.onBackPressed();}
    @Override protected void onDestroy(){super.onDestroy();worker.shutdown();}
}
